package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/projects} — list every project, oldest first, each carrying its client's NAME so
 * the UI shows the name (not the id). Wired by {@code officefloor/rest/api/projects.GET.yml}.
 */
public class ProjectsGet {

    public void service(ProjectRepository projects, ClientRepository clients,
            ObjectResponse<List<ProjectView>> response) {
        Map<Long, String> nameById = clients.findAll().stream()
                .collect(Collectors.toMap(Client::getId, Client::getName));
        List<ProjectView> views = projects.findAllByOrderByIdAsc().stream()
                .map(p -> new ProjectView(p.getId(), p.getName(), p.getClientId(),
                        nameById.get(p.getClientId()), p.isArchived()))
                .collect(Collectors.toList());
        response.send(views);
    }
}

package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/projects/archive} — tuck a project away instead of deleting it: flag it archived
 * so it drops off the default project lists while the row (and everything under it) is kept. Wired
 * by {@code officefloor/rest/api/projects/archive.POST.yml}. The project must exist; the archiving
 * is audited through {@link Audit} so it can be checked back later.
 */
public class ProjectsArchive {

    public void service(@RequestBody ArchiveProject body, ProjectRepository projects, Audit audit,
            ObjectResponse<ProjectView> response) {
        Long id = body.getId();
        Project project = id == null ? null : projects.findById(id).orElse(null);
        if (project == null) {
            throw new IllegalArgumentException("no such project");
        }
        project.setArchived(true);
        Project saved = projects.save(project);
        audit.record("PROJECT_ARCHIVED id=" + id);
        response.send(new ProjectView(saved.getId(), saved.getName(), saved.getClientId(), null,
                saved.isArchived()));
    }
}

package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/projects/remove} — delete a project the user no longer needs and return the row
 * that was removed. Wired by {@code officefloor/rest/api/projects/remove.POST.yml}. The project must
 * exist; the deletion is audited through {@link Audit} so the removal can be checked back later (the
 * UI can only show what still exists).
 */
public class ProjectsRemove {

    public void service(@RequestBody DeleteProject body, ProjectRepository projects, Audit audit,
            ObjectResponse<ProjectView> response) {
        Long id = body.getId();
        Project project = id == null ? null : projects.findById(id).orElse(null);
        if (project == null) {
            throw new IllegalArgumentException("no such project");
        }
        ProjectView removed = new ProjectView(project.getId(), project.getName(),
                project.getClientId(), null, project.isArchived());
        projects.delete(project);
        audit.record("PROJECT_DELETED id=" + id);
        response.send(removed);
    }
}

